def test_client_continues_after_empty_page_with_opaque_cursor():
    cursor = "a+/=?& space☃"
    fetch = pages({"_cursor": None, "items": [], "next_cursor": cursor},
                  {"_cursor": cursor, "items": [item("Z")], "next_cursor": None})
    got = list(VendorClient("http://x", fetch_json=fetch, notices=io.StringIO()).iter_items())
    assert [i["sku"] for i in got] == ["Z"]


def test_client_treats_empty_string_cursor_as_nonterminal():
    from urllib.parse import parse_qs, urlparse

    requests = []

    def fetch(url):
        q = parse_qs(urlparse(url).query, keep_blank_values=True)
        requests.append(q)
        if "cursor" not in q:
            return {"items": [item("A")], "next_cursor": ""}
        assert q["cursor"] == [""]
        return {"items": [item("B")], "next_cursor": None}

    got = list(VendorClient("http://x", fetch_json=fetch, notices=io.StringIO()).iter_items())
    assert [i["sku"] for i in got] == ["A", "B"]
    assert len(requests) == 2


def test_client_does_not_silently_truncate_on_http_410():
    import pytest
    from sync.client import VendorError

    def fetch(url):
        raise VendorError(f"GET {url} -> 410: gone")

    with pytest.raises(VendorError, match="410"):
        list(VendorClient("http://x", fetch_json=fetch, notices=io.StringIO()).iter_items())


def test_merge_preserves_skus_absent_from_feed():
    s = store_with(("OLD", "vendor"), ("M", "manual"))
    r = merge(s, [item("NEW")])
    assert s.skus() == {"OLD", "M", "NEW"}
    assert r.absent_locally(s) == {"OLD", "M"}
