import io
import sqlite3
from sync.client import VendorClient, http_get_json

before = sqlite3.connect('/tmp/catalog-before-cat218.db')
after = sqlite3.connect('data/catalog.db')
old = {r[0]: r for r in before.execute('SELECT * FROM products')}
current = {r[0]: r for r in after.execute('SELECT * FROM products')}
requests = []
def fetch(url):
    requests.append(url)
    return http_get_json(url)
records = list(VendorClient(fetch_json=fetch, notices=io.StringIO()).iter_items())
seen = {r['sku'] for r in records}
for sku, row in old.items():
    if row[3] == 'manual' or sku not in seen:
        assert current.get(sku) == row, f'Protected SKU changed: {sku}'
for item in records:
    sku = item['sku']
    if sku in old and old[sku][3] == 'manual':
        continue
    if item.get('deleted'):
        assert sku not in current, f'Tombstone not applied: {sku}'
    else:
        row = current[sku]
        assert row[1:4] == (item['name'], item['price_paise'], 'vendor'), sku
        if item.get('updated_at'):
            assert row[4] == item['updated_at'], sku
assert set(current) == ((set(old) | {r['sku'] for r in records if not r.get('deleted')}) - {r['sku'] for r in records if r.get('deleted') and (r['sku'] not in old or old[r['sku']][3] == 'vendor')})
assert after.execute('PRAGMA integrity_check').fetchone() == ('ok',)
print(f'Verified {len(records)} feed records across {len(requests)} cursor pages.')
print(f'All {sum(r[3] == "manual" for r in old.values())} manual SKUs and {len(set(old) - seen)} absent local SKUs are unchanged.')
print('Live records, tombstones, final SKU set, and SQLite integrity all verified.')
print('Sync state:', after.execute('SELECT * FROM sync_state').fetchall())
